def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a 2D array to represent the classroom layout
    layout = [[0] * (N + 2 * K) for _ in range(M + 2 * L)]

    # Add horizontal aisles
    for i in range(L):
        layout[i][K:-K] = [1] * (N + 2 * K)
        layout[-(i + 1)][K:-K] = [1] * (N + 2 * K)

    # Add vertical aisles
    for j in range(K):
        layout[:][j] = [1] * (M + 2 * L)
        layout[:][-(j + 1)] = [1] * (M + 2 * L)

    # Count the number of chatting pairs that can be separated by adding an aisle in each possible position
    counts = []
    for i in range(L):
        for j in range(K):
            count = 0
            for x, y, p, q in chatting_pairs:
                if layout[i][j] == layout[p][q]:
                    count += 1
            counts.append(count)

    # Select the most effective positions for aisles
    opt_count = max(counts)
    opt_rows = []
    opt_cols = []
    for i, j in enumerate(counts):
        if j == opt_count:
            opt_rows.append(i // K)
            opt_cols.append(i % K)

    # Return the optimal row and column indices for the aisles
    return ' '.join(map(str, opt_rows)), ' '.join(map(str, opt_cols))
