def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize the count of chatting pairs for each position
    aisle_counts = [[0] * (N + 1) for _ in range(M + 1)]

    # Iterate over the chatting pairs and increment the count for each position
    for chatting_pair in chatting_pairs:
        x1, y1, x2, y2 = chatting_pair
        aisle_counts[x1][y1] += 1
        aisle_counts[x2][y2] += 1

    # Initialize the optimal rows and columns for the aisles
    optimal_rows = []
    optimal_cols = []

    # Iterate over the positions and select the most effective positions for aisles
    for i in range(M + 1):
        for j in range(N + 1):
            if aisle_counts[i][j] > 0 and (i, j) not in optimal_cols:
                optimal_cols.append((i, j))

    # Sort the optimal columns by their index
    optimal_cols.sort(key=lambda x: x[1])

    # Iterate over the optimal columns and select the most effective rows for aisles
    for i, j in optimal_cols:
        if aisle_counts[i][j] > 0 and (i, j) not in optimal_rows:
            optimal_rows.append((i, j))

    # Return the optimal row and column indices for the aisles
    return (", ".join(str(i) for i, _ in optimal_rows), ", ".join(str(j) for _, j in optimal_cols))
