    dp = [[0] * (k+1) for _ in range(n+1)]

    # Initialize the first row and column with 1
    for i in range(k+1):
        dp[0][i] = 1

    # Fill in the rest of the table
    for i in range(1, n+1):
        for j in range(1, k+1):
            # If the current value i is greater than or equal to the current part size j,
            # then we can partition it into current part size j and the remaining (i-j) parts
            if i >= j:
                dp[i][j] = dp[i-j][j] + dp[i][j-1]
            # Otherwise, we can only partition it into current part size j
