    # Base case: When k = 1, there is only one way to partition n into k parts
    for i in range(n + 1):
        dp[i][1] = 1

    # Fill in the table
    for i in range(2, n + 1):
        for j in range(2, k + 1):
            # If x > i, then there are no ways to partition i into j parts
            if x > i:
                dp[i][j] = 0
