def min_remaining_space(V, n, volumes):
    # Base case: if there are no items or the box is already full, return 0
    if n == 0 or sum(volumes) > V:
        return 0

    # Initialize the dynamic programming matrix with -1s
    dp = [[-1 for i in range(n+1)] for j in range(V+1)]

    # Initialize the first row and column of the matrix
    for i in range(n+1):
        dp[0][i] = 0
    for j in range(V+1):
        dp[j][0] = j

    # Fill in the matrix
    for i in range(1, n+1):
        for j in range(1, V+1):
            if volumes[i-1] > j:
                dp[j][i] = dp[j][i-1]
            else:
                dp[j][i] = max(dp[j][i-1], dp[j-volumes[i-1]][i-1] + volumes[i-1])

    # Return the minimum remaining space
    return V - dp[j][n]
